input.command:
# Categorize broken links by type
cat /tmp/broken_links.txt | while read link; do
  case "$link" in
    lesson-*) echo "lesson" ;;
    2026-*) echo "dated-note" ;;
    *) echo "other" ;;
  esac
done | sort | uniq -c | sort -rn

