input.command:
# Categorize remaining broken links
cat /tmp/broken_links_v2.txt | while read link; do
  case "$link" in
    lesson-*) echo "lesson" ;;
    concepts/*|decisions/*|papers/*|patterns/*|experiments/*|projects/*) echo "path-prefixed" ;;
    \{*\}|concept-name|concept1|concept-slug|decision-name|decision-title|paper-name|*template*) echo "template-placeholder" ;;
    [0-9a-f][0-9a-f][0-9a-f][0-9a-f]*) echo "git-hash" ;;
    \"*) echo "quoted-csv" ;;
    2026-*) echo "dated-missing" ;;
    *) echo "other" ;;
  esac
done | sort | uniq -c | sort -rn

