  1→import {
  2→  Decision,
  3→  ReasoningChain,
  4→  DecisionCascade,
  5→  DecisionContradiction,
  6→  ReasoningQueryResult,
  7→  CascadeQueryResult,
  8→  ContradictionQueryResult,
  9→} from '../types/Decision';
 10→import { Notice } from 'obsidian';
 11→
 12→/**
 13→ * SurrealDB Client for Phase 4 Decision Analysis
 14→ *
 15→ * Connects to SurrealDB via HTTP/REST API to query decision reasoning chains,
 16→ * cascades, contradictions, and metadata.
 17→ *
 18→ * Uses LRU caching to minimize redundant queries and improve responsiveness.
 19→ *
 20→ * @example
 21→ * const client = new SurrealDBClient('http://localhost:8000');
 22→ * const reasoning = await client.queryReasoningForDecision('phase-2-track-a-complete');
 23→ * console.log(reasoning.chains);
 24→ */
 25→export class SurrealDBClient {
 26→  private baseUrl: string;
 27→  private readonly cacheSize = 50;
 28→  private queryCache: Map<string, { result: any; timestamp: number }> = new Map();
 29→  private readonly cacheTTL = 5 * 60 * 1000; // 5 minutes
 30→
 31→  constructor(baseUrl: string = 'http://localhost:8000') {
 32→    this.baseUrl = baseUrl.replace(/\/$/, ''); // Remove trailing slash
 33→  }
 34→
 35→  /**
 36→   * Health check - verify SurrealDB is accessible
 37→   */
 38→  async health(): Promise<boolean> {
 39→    try {
 40→      const response = await fetch(`${this.baseUrl}/health`, {
 41→        method: 'GET',
 42→      });
 43→      return response.ok;
 44→    } catch (error) {
 45→      console.error('SurrealDB health check failed:', error);
 46→      return false;
 47→    }
 48→  }
 49→
 50→  /**
 51→   * Execute a SurrealDB query
 52→   * @param query SurrealQL query string
 53→   * @returns Query result
 54→   */
 55→  async executeQuery(query: string): Promise<any> {
 56→    try {
 57→      const response = await fetch(`${this.baseUrl}/sql`, {
 58→        method: 'POST',
 59→        headers: {
 60→          'Content-Type': 'application/json',
 61→          'Accept': 'application/json',
 62→        },
 63→        body: JSON.stringify({ query }),
 64→      });
 65→
 66→      if (!response.ok) {
 67→        throw new Error(`Query failed: ${response.status} ${response.statusText}`);
 68→      }
 69→
 70→      const data = await response.json();
 71→      return data;
 72→    } catch (error) {
 73→      console.error('SurrealDB query error:', error);
 74→      throw error;
 75→    }
 76→  }
 77→
 78→  /**
 79→   * Get or execute cached query
 80→   */
 81→  private async getCachedOrQuery(cacheKey: string, queryFn: () => Promise<any>): Promise<any> {
 82→    // Check cache
 83→    const cached = this.queryCache.get(cacheKey);
 84→    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
 85→      console.debug(`Cache hit for ${cacheKey}`);
 86→      return cached.result;
 87→    }
 88→
 89→    // Execute query
 90→    const result = await queryFn();
 91→
 92→    // Store in cache
 93→    this.queryCache.set(cacheKey, { result, timestamp: Date.now() });
 94→
 95→    // Enforce cache size limit (LRU)
 96→    if (this.queryCache.size > this.cacheSize) {
 97→      const firstKey = this.queryCache.keys().next().value;
 98→      this.queryCache.delete(firstKey);
 99→    }
100→
101→    return result;
102→  }
103→
104→  /**
105→   * Query reasoning chain for a decision
106→   * @param decisionId ID of the decision
107→   * @returns Reasoning chain and metadata
108→   */
109→  async queryReasoningForDecision(decisionId: string): Promise<ReasoningQueryResult | null> {
110→    const cacheKey = `reasoning:${decisionId}`;
111→
112→    return this.getCachedOrQuery(cacheKey, async () => {
113→      try {
114→        const query = `
115→          SELECT * FROM agent_reasoning
116→          WHERE decision_id = '${decisionId}'
117→          ORDER BY step_number ASC
118→        `;
119→
120→        const result = await this.executeQuery(query);
121→
122→        if (!result || !Array.isArray(result) || result.length === 0) {
123→          console.warn(`No reasoning found for decision ${decisionId}`);
124→          return null;
125→        }
126→
127→        // Transform result into ReasoningQueryResult
128→        const chains: ReasoningChain[] = result.map((row: any) => ({
129→          id: row.id || `chain-${decisionId}`,
130→          decision_id: decisionId,
131→          steps: row.steps || [],
132→          reasoning_type: row.reasoning_type || 'hybrid',
133→          confidence: row.confidence || 0.5,
134→          assumptions: row.assumptions || [],
135→          timestamp: row.timestamp || new Date().toISOString(),
136→        }));
137→
138→        return {
139→          decision: { id: decisionId } as Decision,
140→          chains,
141→          high_confidence: chains.some(c => c.confidence > 0.8),
142→          timestamp: new Date().toISOString(),
143→        };
144→      } catch (error) {
145→        console.error(`Failed to query reasoning for ${decisionId}:`, error);
146→        return null;
147→      }
148→    });
149→  }
150→
151→  /**
152→   * Analyze decision cascades (downstream impacts)
153→   * @param decisionId Source decision ID
154→   * @param depth Maximum cascade depth (1-5)
155→   * @returns Cascade analysis
156→   */
157→  async analyzeDecisionCascades(
158→    decisionId: string,
159→    depth: number = 3
160→  ): Promise<CascadeQueryResult | null> {
161→    const cacheKey = `cascades:${decisionId}:${depth}`;
162→
163→    return this.getCachedOrQuery(cacheKey, async () => {
164→      try {
165→        // Query direct cascades
166→        const query = `
167→          SELECT * FROM decision_cascades
168→          WHERE source_decision_id = '${decisionId}'
169→          LIMIT 100
170→        `;
171→
172→        const result = await this.executeQuery(query);
173→
174→        if (!result || !Array.isArray(result)) {
175→          return null;
176→        }
177→
178→        const cascades: DecisionCascade[] = result.map((row: any) => ({
179→          source_decision_id: decisionId,
180→          target_decision_id: row.target_decision_id,
181→          dependency_type: row.dependency_type,
182→          impact_level: row.impact_level,
183→          description: row.description,
184→        }));
185→
186→        const criticalCount = cascades.filter(c => c.impact_level === 'critical').length;
187→
188→        return {
189→          source_decision: { id: decisionId } as Decision,
190→          cascades,
191→          total_impacted: cascades.length,
192→          critical_impact_count: criticalCount,
193→          timestamp: new Date().toISOString(),
194→        };
195→      } catch (error) {
196→        console.error(`Failed to query cascades for ${decisionId}:`, error);
197→        return null;
198→      }
199→    });
200→  }
201→
202→  /**
203→   * Detect contradictions between decision and lessons
204→   * @param decisionId Decision ID to check
205→   * @returns Contradictions found
206→   */
207→  async detectContradictions(decisionId: string): Promise<ContradictionQueryResult | null> {
208→    const cacheKey = `contradictions:${decisionId}`;
209→
210→    return this.getCachedOrQuery(cacheKey, async () => {
211→      try {
212→        const query = `
213→          SELECT * FROM decision_contradictions
214→          WHERE decision_id = '${decisionId}'
215→          ORDER BY severity DESC
216→        `;
217→
218→        const result = await this.executeQuery(query);
219→
220→        if (!result || !Array.isArray(result)) {
221→          return null;
222→        }
223→
224→        const contradictions: DecisionContradiction[] = result.map((row: any) => ({
225→          decision_id: decisionId,
226→          lesson_id: row.lesson_id,
227→          challenge_type: row.challenge_type,
228→          severity: row.severity,
229→          description: row.description,
230→        }));
231→
232→        // Count by severity
233→        const severityCounts: Record<string, number> = {};
234→        contradictions.forEach(c => {
235→          severityCounts[c.severity] = (severityCounts[c.severity] || 0) + 1;
236→        });
237→
238→        return {
239→          decision: { id: decisionId } as Decision,
240→          contradictions,
241→          severity_counts: severityCounts,
242→          timestamp: new Date().toISOString(),
243→        };
244→      } catch (error) {
245→        console.error(`Failed to query contradictions for ${decisionId}:`, error);
246→        return null;
247→      }
248→    });
249→  }
250→
251→  /**
252→   * Fetch decision metadata
253→   * @param decisionId Decision ID
254→   * @returns Full decision details
255→   */
256→  async fetchDecisionMetadata(decisionId: string): Promise<Decision | null> {
257→    const cacheKey = `decision:${decisionId}`;
258→
259→    return this.getCachedOrQuery(cacheKey, async () => {
260→      try {
261→        const query = `
262→          SELECT * FROM decisions
263→          WHERE id = '${decisionId}'
264→        `;
265→
266→        const result = await this.executeQuery(query);
267→
268→        if (!result || !Array.isArray(result) || result.length === 0) {
269→          return null;
270→        }
271→
272→        const row = result[0];
273→        return {
274→          id: decisionId,
275→          title: row.title || '',
276→          chosen_option: row.chosen_option || '',
277→          rationale: row.rationale || '',
278→          reasoning_type: row.reasoning_type || 'hybrid',
279→          confidence_score: row.confidence_score || 0.5,
280→          reasoning_chain: {} as ReasoningChain,
281→          alternatives_rejected: row.alternatives_rejected || [],
282→          related_papers: row.related_papers || [],
283→          status: row.status || 'active',
284→          timestamp: row.timestamp || new Date().toISOString(),
285→          vault_path: row.vault_path,
286→        };
287→      } catch (error) {
288→        console.error(`Failed to fetch metadata for ${decisionId}:`, error);
289→        return null;
290→      }
291→    });
292→  }
293→
294→  /**
295→   * Query high-confidence reasoning (>threshold)
296→   * @param threshold Minimum confidence (0.0-1.0)
297→   * @returns List of high-confidence decisions
298→   */
299→  async queryHighConfidenceReasoning(threshold: number = 0.8): Promise<Decision[]> {
300→    const cacheKey = `high-confidence:${threshold}`;
301→
302→    return this.getCachedOrQuery(cacheKey, async () => {
303→      try {
304→        const query = `
305→          SELECT * FROM decisions
306→          WHERE confidence_score >= ${threshold}
307→          ORDER BY confidence_score DESC
308→          LIMIT 50
309→        `;
310→
311→        const result = await this.executeQuery(query);
312→
313→        if (!result || !Array.isArray(result)) {
314→          return [];
315→        }
316→
317→        return result.map((row: any) => ({
318→          id: row.id,
319→          title: row.title || '',
320→          chosen_option: row.chosen_option || '',
321→          rationale: row.rationale || '',
322→          reasoning_type: row.reasoning_type || 'hybrid',
323→          confidence_score: row.confidence_score || 0.5,
324→          reasoning_chain: {} as ReasoningChain,
325→          status: row.status || 'active',
326→          timestamp: row.timestamp || new Date().toISOString(),
327→        }));
328→      } catch (error) {
329→        console.error('Failed to query high-confidence reasoning:', error);
330→        return [];
331→      }
332→    });
333→  }
334→
335→  /**
336→   * Query decisions by reasoning type
337→   * @param type Reasoning type filter
338→   * @returns Matching decisions
339→   */
340→  async queryReasoningByType(
341→    type: 'research' | 'pattern' | 'intuition' | 'convention' | 'hybrid'
342→  ): Promise<Decision[]> {
343→    const cacheKey = `by-type:${type}`;
344→
345→    return this.getCachedOrQuery(cacheKey, async () => {
346→      try {
347→        const query = `
348→          SELECT * FROM decisions
349→          WHERE reasoning_type = '${type}'
350→          ORDER BY confidence_score DESC
351→          LIMIT 50
352→        `;
353→
354→        const result = await this.executeQuery(query);
355→
356→        if (!result || !Array.isArray(result)) {
357→          return [];
358→        }
359→
360→        return result.map((row: any) => ({
361→          id: row.id,
362→          title: row.title || '',
363→          chosen_option: row.chosen_option || '',
364→          rationale: row.rationale || '',
365→          reasoning_type: row.reasoning_type || 'hybrid',
366→          confidence_score: row.confidence_score || 0.5,
367→          reasoning_chain: {} as ReasoningChain,
368→          status: row.status || 'active',
369→          timestamp: row.timestamp || new Date().toISOString(),
370→        }));
371→      } catch (error) {
372→        console.error(`Failed to query by type ${type}:`, error);
373→        return [];
374→      }
375→    });
376→  }
377→
378→  /**
379→   * Clear cache (useful after database updates)
380→   */
381→  clearCache(): void {
382→    this.queryCache.clear();
383→    console.log('SurrealDB query cache cleared');
384→  }
385→
386→  /**
387→   * Get cache statistics
388→   */
